273	/// Starts the checker over a program rooted at `roots` (the files of the components that export something, in the
274	/// order of the output) and opens it, on a thread of its own, for a run with `project_root`, `tsconfig` and
275	/// `timeout`; `keep` has it note what it reads for the kept answer. `None` when there is nothing to ask about.
276	pub fn start_early(
277	    project_root: Utf8PathBuf,
278	    tsconfig: Option<Utf8PathBuf>,
279	    timeout: Duration,
280	    roots: &[Utf8PathBuf],
281	    keep: bool,
282	) -> Option<EarlyStart> {
283	    if roots.is_empty() {
284	        return None;
285	    }
286	    let roots: Vec<String> = roots.iter().map(|file| file.to_string()).collect();
287	    let reads = keep.then(|| Arc::new(kept::Reads::default()));
288	    let (root, config, files, noting) = (project_root.clone(), tsconfig.clone(), roots.clone(), reads.clone());
289	    let handle = std::thread::Builder::new()
290	        .name("caliper-early".into())
291	        .spawn(move || {
292	            let threads = std::thread::available_parallelism().map_or(1, |count| count.get().min(CONVERTER_THREADS));
293	            let runtime =
294	                tokio::runtime::Builder::new_multi_thread().worker_threads(threads).enable_all().build().ok()?;
295	            let programs = CHECKER_PROGRAMS.min(files.len().div_ceil(MIN_FILES_PER_PROGRAM)).max(1);
296	            let checker = Backend::start_noting(&root, programs, noting).ok()?;
297	            let tsconfig = config.as_ref().map(|path| path.as_str());
298	            let count = checker.parallel_programs();
299	            let opened =
300	                runtime.block_on(Rpc::open_programs(checker.client(), timeout, tsconfig, &files, false, count));
301	            let programs = opened
302	                .map(|programs| programs.into_iter().map(Arc::new).collect())
303	                .map_err(|error| SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")));
304	            Some(Opened { runtime, checker, programs })
305	        })
306	        .ok();
307	    Some(EarlyStart { handle, project_root, tsconfig, timeout, roots, reads })
308	}
