401	                    early_roots = early_roots.len(),
402	                    roots = files.len(),
403	                    "the session opened early is the request's"
404	                );
405	                let outcome = match programs {
406	                    Ok(programs) => runtime.block_on(async {
407	                        let started = std::time::Instant::now();
408	                        let answered = answer_opened(programs, &request, &files, started, &Lanes::of(taken)).await;
409	                        checker.shutdown().await;
410	                        answered
411	                    }),
412	                    Err(unavailable) => {
413	                        runtime.block_on(checker.shutdown());
414	                        unavailable
415	                    }
416	                };
417	                if teardown == Teardown::OneShot {
418	                    std::mem::forget(runtime);
419	                }
420	                return (outcome, taken);
421	            }
422	            None => runtime.block_on(checker.shutdown()),
423	        }
424	    }
425	    let threads = std::thread::available_parallelism().map_or(1, |count| count.get().min(CONVERTER_THREADS));
426	    let built = tokio::runtime::Builder::new_multi_thread().worker_threads(threads).enable_all().build();
427	    let runtime = match built {
428	        Ok(runtime) => runtime,
429	        Err(error) => {
430	            let unavailable = SemanticOutcome::unavailable(format!("could not start an async runtime: {error}"));
