443	/// `updateSnapshot` (`reconfigurePrograms`), which reads every file as the snapshot holds it and parses only the roots
444	/// added; the checker works the program's files, globals and ambient declarations out again from the new roots, so a
445	/// file no root reaches any more declares nothing. The snapshots they replace are released, and the lanes' are the new
446	/// ones' own to release ([`Lanes::Each`]). Any failure is the caller's to answer by starting the checker again: no
447	/// answer is given from a partly rooted set.
448	async fn reroot(old: Vec<Arc<Rpc>>, files: &[String]) -> Result<Vec<Arc<Rpc>>, CallError> {
449	    let files: Arc<[String]> = files.into();
450	    let mut tasks = JoinSet::new();
451	    for (lane, rpc) in old.iter().enumerate() {
452	        let (rpc, files) = (rpc.clone(), files.clone());
453	        tasks.spawn(async move { (lane, rpc.updated(&[], &[], Some(&files)).await) });
454	    }
455	    let mut rooted: Vec<Option<Rpc>> = old.iter().map(|_| None).collect();
456	    while let Some(joined) = tasks.join_next().await {
457	        let (lane, updated) = joined.map_err(|error| CallError::Fatal(format!("a root update failed: {error}")))?;
458	        if let Some(slot) = rooted.get_mut(lane) {
459	            *slot = Some(updated?);
460	        }
461	    }
462	    let rooted: Option<Vec<Arc<Rpc>>> = rooted.into_iter().map(|rpc| rpc.map(Arc::new)).collect();
463	    let rooted = rooted.ok_or_else(|| CallError::Fatal("a lane was not rooted".to_string()))?;
464	    if let Some(first) = old.first() {
465	        first.release().await;
466	    }
467	    Ok(rooted)
468	}
