331	/// Keeps `outcome` at `file` for the request `key` names, with the questions `reads` noted. Nothing is kept for an
332	/// outcome with a diagnostic or a run that read more than one state of the disk; a failure to write is logged and
333	/// otherwise ignored (the next run asks the checker again).
334	pub(crate) fn save(file: &Utf8Path, key: u128, reads: &Reads, outcome: &SemanticOutcome) {
335	    if !outcome.diagnostics.is_empty() {
336	        return;
337	    }
338	    let Some(reads) = reads.settled() else {
339	        tracing::debug!("the checker read a file that changed during the run; its answer is not kept");
340	        return;
341	    };
342	    let written = (|| -> Result<(), String> {
343	        let mut bytes = rmp_serde::to_vec(&Header::of(key)).map_err(|error| error.to_string())?;
344	        bytes.extend(rmp_serde::to_vec(&reads).map_err(|error| error.to_string())?);
345	        bytes.extend(outcome.to_bytes()?);
346	        let dir = file.parent().ok_or_else(|| "no directory".to_string())?;
347	        std::fs::create_dir_all(dir).map_err(|error| error.to_string())?;
348	        // A name of its own per process, so two runs sharing the directory do not write one temporary file.
349	        let temporary = dir.join(format!("{FILE}.{}.tmp", std::process::id()));
350	        let result = std::fs::write(&temporary, &bytes).and_then(|()| std::fs::rename(&temporary, file));
351	        if result.is_err() {
352	            std::fs::remove_file(&temporary).ok();
353	        }
354	        result.map_err(|error| error.to_string())
355	    })();
356	    if let Err(error) = written {
357	        tracing::debug!("could not keep the checker's answer at {file}: {error}");
358	    }
359	}
